// @generated by:gauntlet run:godseye-e06-completion
import { randomBytes, randomUUID } from "node:crypto";
import { once } from "node:events";
import { mkdtemp, rm } from "node:fs/promises";
import { createServer } from "node:net";
import { tmpdir } from "node:os";
import { join, resolve, sep } from "node:path";
import { setTimeout as wait } from "node:timers/promises";
import { serve as serveHttp } from "@hono/node-server";
import { Hono } from "hono";
import { Inngest } from "inngest";
import { serve } from "inngest/hono";
import pg from "pg";
import { describe, expect, it } from "vitest";
import { startNativeInngest } from "../apps/control-api/src/inngest-native.js";
import { inspectWorkflowStorage } from "../apps/jobs-runtime/src/storage.js";
import { createInngestPersistenceLab } from "./inngest-persistence-host.js";

async function port() {
  const server = createServer();
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const address = server.address();
  if (!address || typeof address === "string") throw new Error("Native persistence port missing");
  await new Promise<void>((done) => server.close(() => done()));
  return address.port;
}

async function until(check: () => Promise<boolean>, label: string, timeoutMs = 45_000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (await check()) return;
    await wait(100);
  }
  throw new Error(`Native persistence observation deadline: ${label}`);
}

async function removeOwnedDirectory(directory: string) {
  const owned = resolve(directory);
  if (!owned.startsWith(`${resolve(tmpdir())}${sep}godseye-inngest-persistence-`))
    throw new Error("Unsafe persistence laboratory cleanup path");
  await rm(owned, { recursive: true, force: true });
}

describe.runIf(process.env.GODSEYE_INNGEST_PERSISTENCE_LAB === "enabled")(
  "real Inngest PostgreSQL/Redis persistence",
  () => {
    it("T-E06-P02 resumes a persisted sleep once after the engine, PostgreSQL and authenticated AOF Redis restart", async () => {
      const lab = await createInngestPersistenceLab();
      const storage = lab.cells[0];
      if (!storage) throw new Error("Native workflow storage missing");
      const directory = await mkdtemp(join(tmpdir(), "godseye-inngest-persistence-"));
      const [
        enginePort,
        workerPort,
        applicationPort,
        gatewayPort,
        gatewayGrpcPort,
        executorGrpcPort,
      ] = await Promise.all(Array.from({ length: 6 }, () => port()));
      if (
        !enginePort ||
        !workerPort ||
        !applicationPort ||
        !gatewayPort ||
        !gatewayGrpcPort ||
        !executorGrpcPort
      )
        throw new Error("Native persistence listener binding missing");
      const cell = {
        projectId: randomUUID(),
        environmentId: randomUUID(),
        enginePort,
        workerPort,
        applicationPort,
        gatewayPort,
        gatewayGrpcPort,
        executorGrpcPort,
      };
      const baseUrl = `http://127.0.0.1:${enginePort}`;
      const sdkUrl = `http://127.0.0.1:${workerPort}/api/inngest`;
      const material = {
        event: randomBytes(32).toString("hex"),
        signing: randomBytes(32).toString("hex"),
        auth: randomBytes(48).toString("base64url"),
      };
      const client = new Inngest({
        id: `durable-${cell.environmentId}`,
        baseUrl,
        eventKey: material.event,
        signingKey: material.signing,
        isDev: false,
      });
      const before: string[] = [],
        after: string[] = [];
      const fn = client.createFunction(
        { id: "durable-sleep", triggers: { event: "lab/durable.sleep" }, retries: 0 },
        async ({ event, step }) => {
          await step.run("before-restart", () => {
            before.push(event.id ?? "missing");
            return { recorded: true };
          });
          await step.sleep("persisted-wait", "30s");
          return step.run("after-restart", () => {
            after.push(event.id ?? "missing");
            return { completed: true };
          });
        },
      );
      const app = new Hono();
      app.on(
        ["GET", "POST", "PUT"],
        "/api/inngest",
        serve({ client, functions: [fn], serveOrigin: `http://127.0.0.1:${workerPort}` }),
      );
      const listener = serveHttp({ fetch: app.fetch, hostname: "127.0.0.1", port: workerPort });
      let native: Awaited<ReturnType<typeof startNativeInngest>> | undefined;
      let failures = 0;
      const start = () =>
        startNativeInngest({
          cell,
          directory,
          sdkUrl,
          material,
          persistence: storage,
          onFailure: () => {
            failures++;
          },
        });
      try {
        if (!listener.listening) await once(listener, "listening");
        native = await start();
        const eventId = randomUUID();
        const sent = await client.send({
          id: eventId,
          name: "lab/durable.sleep",
          data: { revision: 1 },
        });
        await until(async () => before.length === 1, "initial durable step");
        // A registered function alone is insufficient: observe its queued Redis state after the step.
        await until(
          async () => Number(await lab.inspectRedis(0, ["DBSIZE"])) > 0,
          "external queue data",
        );
        const persistence = await lab.inspectRedis(0, ["INFO", "persistence"]);
        expect(persistence.includes("aof_enabled:1")).toBe(true);
        expect(persistence.includes("aof_last_write_status:ok")).toBe(true);
        expect(after).toHaveLength(0);

        const beforePool = new pg.Pool({
          connectionString: storage.postgresUri,
          connectionTimeoutMillis: 5000,
        });
        let tables: string[] = [];
        try {
          tables = (
            await beforePool.query<{ table_name: string }>(
              "SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE'",
            )
          ).rows.map((row) => row.table_name);
          expect(tables.some((name) => /event|function|run/.test(name))).toBe(true);
          expect(
            (
              await beforePool.query<{ rolsuper: boolean }>(
                "SELECT rolsuper FROM pg_roles WHERE rolname=current_user",
              )
            ).rows[0]?.rolsuper,
          ).toBe(false);
          expect(
            Number(
              (
                await beforePool.query<{ total: string }>(
                  "SELECT count(*) AS total FROM events WHERE event_id=$1",
                  [eventId],
                )
              ).rows[0]?.total ?? 0,
            ),
          ).toBe(1);
        } finally {
          await beforePool.end();
        }

        await native.close();
        native = undefined;
        await lab.restartRedis(0);
        await lab.restartPostgres(0);
        expect(Number(await lab.inspectRedis(0, ["DBSIZE"])) > 0).toBe(true);
        native = await start();
        await until(async () => after.length === 1, "resumed terminal step", 60_000);
        await wait(1000);

        expect(sent.ids).toHaveLength(1);
        expect(before).toEqual([eventId]);
        expect(after).toEqual([eventId]);
        expect(failures).toBe(0);
        const afterPool = new pg.Pool({
          connectionString: storage.postgresUri,
          connectionTimeoutMillis: 5000,
        });
        try {
          const reopened = (
            await afterPool.query<{ table_name: string }>(
              "SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE'",
            )
          ).rows.map((row) => row.table_name);
          expect(reopened.sort()).toEqual(tables.sort());
          let durableRows = 0;
          for (const table of tables.filter((name) => /event|function|run/.test(name))) {
            if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(table))
              throw new Error("Unexpected native workflow table identifier");
            durableRows += Number(
              (await afterPool.query<{ total: string }>(`SELECT count(*) AS total FROM "${table}"`))
                .rows[0]?.total ?? 0,
            );
          }
          expect(durableRows).toBeGreaterThan(0);
          expect(
            Number(
              (
                await afterPool.query<{ total: string }>(
                  "SELECT count(*) AS total FROM function_finishes finish JOIN function_runs run ON finish.run_id=run.run_id JOIN events event ON run.event_id=event.internal_id WHERE event.event_id=$1",
                  [eventId],
                )
              ).rows[0]?.total ?? 0,
            ),
          ).toBe(1);
        } finally {
          await afterPool.end();
        }
      } finally {
        await native?.close();
        if ("closeAllConnections" in listener) listener.closeAllConnections();
        await new Promise<void>((done) => listener.close(() => done()));
        await lab.close();
        await removeOwnedDirectory(directory);
      }
    }, 180_000);

    it("T-E06-P01 T-E06-P03 authenticates independent workflow stores and refuses foreign authority or an unavailable dependency", async () => {
      const lab = await createInngestPersistenceLab(2);
      try {
        const [first, second] = lab.cells;
        if (!first || !second) throw new Error("Two workflow storage cells required");
        const firstProof = await inspectWorkflowStorage(first);
        const secondProof = await inspectWorkflowStorage(second);
        expect(firstProof.database).toBe("workflow");
        expect(secondProof.database).toBe("workflow");
        expect(firstProof.redisInstanceId === secondProof.redisInstanceId).toBe(false);
        const wrongPg = new URL(second.postgresUri);
        wrongPg.password = new URL(first.postgresUri).password;
        await expect(
          inspectWorkflowStorage({ ...second, postgresUri: wrongPg.href }),
        ).rejects.toThrow("External workflow storage failed");
        const wrongRedis = new URL(second.redisUri);
        wrongRedis.password = new URL(first.redisUri).password;
        await expect(
          inspectWorkflowStorage({ ...second, redisUri: wrongRedis.href }),
        ).rejects.toThrow("External workflow storage failed");
        const absentRedis = new URL(first.redisUri);
        absentRedis.port = String(await port());
        await expect(
          inspectWorkflowStorage({ ...first, redisUri: absentRedis.href }),
        ).rejects.toThrow("External workflow storage failed");
        expect(await lab.inspectRedis(0, ["PING"])).toBe("PONG");
        expect(await lab.inspectRedis(1, ["PING"])).toBe("PONG");
      } finally {
        await lab.close();
      }
    }, 120_000);
  },
);
